//! GPU-accelerated IQ2/IQ3/IQ1 and Q2_K/Q3_K matmul, dispatched through
//! `BatchedLinearRuntime`.
//!
//! One entry point serves the seven 2/3/1-bit formats (IQ2_XXS, IQ2_XS,
//! IQ2_S, IQ3_XXS, IQ3_S, IQ1_S, IQ1_M) plus the five k-quants
//! (Q2_K, Q3_K, Q4_K, Q5_K, Q6_K, hand-written shaders mirroring the
//! `avx2`/`mod.rs` kernels bit for bit):
//! each has its own shader (`shaders/glsl/<t>_matmul.comp`, generated by
//! `shaders/gen_iq_shaders.py` for the IQ types) and its own cached
//! runtime slot, but the lifecycle is identical to `matmul_q4k.rs`:
//! lazily-created `BatchedLinearRuntime` grown monotonically over shapes,
//! serialized per format, `UnsupportedShape` falls back to CPU per call.
//!
//! ## Validation
//!
//! `iq_and_k_quant_gpu_matches_cpu_avx2_bitwise_on_real_weights` proves the
//! GPU results bit-identical to the CPU AVX2 kernels, which are themselves
//! bitwise-verified against llama.cpp.

use std::collections::BTreeMap;
use std::sync::{Mutex, OnceLock};

use super::ops::{BatchedLinearRuntime, GpuMatmulSpec, GpuWeightFormat};
use super::{VulkanContext, VulkanError};

struct IQRuntime {
    runtime: BatchedLinearRuntime,
    max_rows: usize,
    max_n_in: usize,
    max_n_out: usize,
}

fn runtime_slot() -> &'static Mutex<BTreeMap<GpuWeightFormat, IQRuntime>> {
    static IQ_RUNTIME: OnceLock<Mutex<BTreeMap<GpuWeightFormat, IQRuntime>>> = OnceLock::new();
    IQ_RUNTIME.get_or_init(|| Mutex::new(BTreeMap::new()))
}

pub(crate) fn release_shared_runtime() -> Result<(), VulkanError> {
    if let Ok(mut slot) = runtime_slot().lock() {
        slot.clear();
    }
    Ok(())
}

const DEFAULT_MAX_ROWS: usize = 4;

/// Run one IQ2/IQ3/IQ1 or Q2_K/Q3_K/Q4_K/Q5_K/Q6_K matmul on the GPU.
/// `format` selects the shader and block layout; `weight` must be the GGUF
/// byte stream of that format (rows × (n_in / 256) × block bytes). See
/// `matmul_q4_k` for the error contract: `UnsupportedShape` falls back to CPU
/// per call, everything else marks the device broken.
/// CPU reference dot for a GPU IQ format. Returns the dispatched function
/// (AVX2 on x86) so the GPU-vs-CPU comparison uses the production CPU kernel.
pub fn cpu_iq_vec_dot(format: GpuWeightFormat) -> fn(&[u8], &[crate::ops::quant::BlockQ8K]) -> f32 {
    match format {
        GpuWeightFormat::IQ2_XXS => crate::ops::quant::vec_dot_iq2_xxs_q8k,
        GpuWeightFormat::IQ2_XS => crate::ops::quant::vec_dot_iq2_xs_q8k,
        GpuWeightFormat::IQ2_S => crate::ops::quant::vec_dot_iq2_s_q8k,
        GpuWeightFormat::IQ3_XXS => crate::ops::quant::vec_dot_iq3_xxs_q8k,
        GpuWeightFormat::IQ3_S => crate::ops::quant::vec_dot_iq3_s_q8k,
        GpuWeightFormat::IQ1_S => crate::ops::quant::vec_dot_iq1_s_q8k,
        GpuWeightFormat::IQ1_M => crate::ops::quant::vec_dot_iq1_m_q8k,
        GpuWeightFormat::Q2_K => crate::ops::quant::vec_dot_q2k_q8k,
        GpuWeightFormat::Q3_K => crate::ops::quant::vec_dot_q3k_q8k,
        GpuWeightFormat::Q4_K => crate::ops::quant::vec_dot_q4k_q8k,
        GpuWeightFormat::Q5_K => crate::ops::quant::vec_dot_q5k_q8k,
        GpuWeightFormat::Q6_K => crate::ops::quant::vec_dot_q6k_q8k,
        _ => unreachable!("cpu_iq_vec_dot is only valid for IQ/K-quant low-bit formats"),
    }
}

pub fn matmul_iq(
    context: &VulkanContext,
    format: GpuWeightFormat,
    weight: &[u8],
    input: &[f32],
    rows: usize,
    n_in: usize,
    n_out: usize,
    output: &mut [f32],
) -> Result<(), VulkanError> {
    let (block_elements, block_bytes, _) = format.layout();
    debug_assert_eq!(
        weight.len(),
        n_out * (n_in / block_elements) * block_bytes,
        "IQ weight layout is rows × (n_in / {block_elements}) blocks × {block_bytes} bytes/block"
    );
    debug_assert!(input.len() >= rows * n_in, "input shorter than rows × n_in");
    debug_assert!(
        output.len() >= rows * n_out,
        "output shorter than rows × n_out"
    );

    let local_slot = Mutex::new(BTreeMap::new());
    let slot = if crate::ops::float::is_shared_vulkan_context(context) {
        runtime_slot()
    } else {
        &local_slot
    };
    let mut guard = slot
        .lock()
        .map_err(|_| VulkanError::InitFailed("IQ runtime mutex poisoned".into()))?;

    let need_rebuild = match guard.get(&format) {
        Some(rt) => rows > rt.max_rows || n_in > rt.max_n_in || n_out > rt.max_n_out,
        None => true,
    };
    if need_rebuild {
        let (new_max_rows, new_max_n_in, new_max_n_out) = match guard.get(&format) {
            Some(rt) => (
                rt.max_rows.max(rows),
                rt.max_n_in.max(n_in),
                rt.max_n_out.max(n_out),
            ),
            None => (DEFAULT_MAX_ROWS.max(rows), n_in, n_out),
        };
        // The shared slot borrows the singleton; local_slot drops before the
        // caller's context borrow ends, so neither runtime can outlive its context.
        let static_ctx: &'static VulkanContext = unsafe { std::mem::transmute(context) };
        match BatchedLinearRuntime::new(static_ctx, new_max_rows, new_max_n_in, new_max_n_out, 256)
        {
            Ok(runtime) => {
                guard.insert(
                    format,
                    IQRuntime {
                        runtime,
                        max_rows: new_max_rows,
                        max_n_in: new_max_n_in,
                        max_n_out: new_max_n_out,
                    },
                );
            }
            Err(error) => {
                super::mark_gpu_broken(&error.to_string());
                return Err(error);
            }
        }
    }

    let runtime = guard.get_mut(&format).expect("runtime was just installed");
    match runtime.runtime.matmul_rows(
        weight,
        GpuMatmulSpec::from(format),
        input,
        rows,
        n_in,
        n_out,
        output,
    ) {
        Ok(()) => Ok(()),
        Err(error) => {
            // UnsupportedShape is a per-call failure: the GPU stays alive for
            // other shapes, but this matmul must fall back to CPU. Anything
            // else marks the device broken.
            if !matches!(error, VulkanError::UnsupportedShape(_)) {
                super::mark_gpu_broken(&error.to_string());
            }
            Err(error)
        }
    }
}

#[cfg(all(test, feature = "vulkan"))]
mod gpu_cpu_parity {

    use super::*;
    use crate::core::loader::GGUFLoader;

    /// Every IQ type plus the five k-quants: the GPU matmul over a real model
    /// tensor must be bit-identical to the CPU AVX2 kernel (which is itself
    /// bitwise-verified against llama.cpp).
    ///
    /// The tensor is selected by `ggml_type`, not by name: UD (Unsloth
    /// Dynamic) mixed quants deliberately keep the attention layers at a
    /// higher-precision format (e.g. UD-IQ1_S ships `blk.0.attn_q.weight`
    /// as IQ2_XXS and only the FFN tensors as IQ1_S), so name-based picks
    /// silently grabbed the wrong layout and tripped the size check. The
    /// UD-Q2_K_XL file mixes 72×Q2K and 69×Q3K tensors, so it validates both
    /// low-bit k-quant cases; UD-Q3_K_XL mixes Q3K/Q4K/Q5K/Q6K, so it
    /// validates the three remaining k-quants.
    #[test]
    fn iq_and_k_quant_gpu_matches_cpu_avx2_bitwise_on_real_weights() {
        let context = match VulkanContext::new() {
            Ok(ctx) => ctx,
            Err(_) => return,
        };
        if context.is_software_icd() {
            eprintln!("[skip] software ICD detected");
            return;
        }
        use crate::core::tensor::GGMLType;
        let cases: [(&str, &str, GpuWeightFormat, GGMLType); 12] = [
            (
                "iq2_xxs",
                "models/Qwen3-0.6B-GGUF/Qwen3-0.6B-UD-IQ2_XXS.gguf",
                GpuWeightFormat::IQ2_XXS,
                GGMLType::IQ2_XXS,
            ),
            (
                "iq2_xs",
                "models/Qwen3-0.6B-GGUF/Qwen3-0.6B-IQ2_XS.gguf",
                GpuWeightFormat::IQ2_XS,
                GGMLType::IQ2_XS,
            ),
            // The bartowski IQ2_S file contains no IQ2_S tensors at all
            // (137×IQ2_XS + 59×IQ3_S); the UD-IQ1_S file ships genuine
            // IQ2_S FFN-down tensors, so it validates the format instead.
            (
                "iq2_s",
                "models/Qwen3-0.6B-GGUF/Qwen3-0.6B-UD-IQ1_S.gguf",
                GpuWeightFormat::IQ2_S,
                GGMLType::IQ2_S,
            ),
            (
                "iq3_xxs",
                "models/Qwen3-0.6B-GGUF/Qwen3-0.6B-UD-IQ3_XXS.gguf",
                GpuWeightFormat::IQ3_XXS,
                GGMLType::IQ3_XXS,
            ),
            (
                "iq3_s",
                "models/Qwen3-0.6B-GGUF/Qwen3-0.6B-IQ3_S.gguf",
                GpuWeightFormat::IQ3_S,
                GGMLType::IQ3_S,
            ),
            (
                "iq1_s",
                "models/Qwen3-0.6B-GGUF/Qwen3-0.6B-UD-IQ1_S.gguf",
                GpuWeightFormat::IQ1_S,
                GGMLType::IQ1_S,
            ),
            (
                "iq1_m",
                "models/Qwen3-0.6B-GGUF/Qwen3-0.6B-UD-IQ1_M.gguf",
                GpuWeightFormat::IQ1_M,
                GGMLType::IQ1_M,
            ),
            (
                "q2_k",
                "models/Qwen3-0.6B-GGUF/Qwen3-0.6B-UD-Q2_K_XL.gguf",
                GpuWeightFormat::Q2_K,
                GGMLType::Q2K,
            ),
            (
                "q3_k",
                "models/Qwen3-0.6B-GGUF/Qwen3-0.6B-UD-Q2_K_XL.gguf",
                GpuWeightFormat::Q3_K,
                GGMLType::Q3K,
            ),
            (
                "q4_k",
                "models/Qwen3-0.6B-GGUF/Qwen3-0.6B-UD-Q3_K_XL.gguf",
                GpuWeightFormat::Q4_K,
                GGMLType::Q4K,
            ),
            (
                "q5_k",
                "models/Qwen3-0.6B-GGUF/Qwen3-0.6B-UD-Q3_K_XL.gguf",
                GpuWeightFormat::Q5_K,
                GGMLType::Q5K,
            ),
            (
                "q6_k",
                "models/Qwen3-0.6B-GGUF/Qwen3-0.6B-UD-Q3_K_XL.gguf",
                GpuWeightFormat::Q6_K,
                GGMLType::Q6K,
            ),
        ];
        for (label, path, format, want_type) in cases {
            let loader = match GGUFLoader::from_file(path) {
                Ok(l) => l,
                Err(_) => {
                    eprintln!("[skip] {path} not present");
                    continue;
                }
            };
            let (tensor_name, n_in, n_out) = loader
                .tensors()
                .iter()
                .find(|t| t.ggml_type == want_type && t.dims.len() == 2 && t.dims[0] % 256 == 0)
                .map(|t| (t.name.clone(), t.dims[0] as usize, t.dims[1] as usize))
                .unwrap_or_else(|| panic!("{path}: no {want_type:?} tensor — wrong model file?"));
            let (block_elements, block_bytes, _) = format.layout();
            let weight = loader.tensor_slice(&tensor_name).unwrap();
            let expected_len = n_out * (n_in / block_elements) * block_bytes;
            if weight.len() != expected_len {
                eprintln!(
                    "[skip] {label}: tensor size {} != expected {}",
                    weight.len(),
                    expected_len
                );
                continue;
            }

            // Pseudo-random activations: real streams are irrational-ish f32s,
            // while the historical (i%97-48)/32 pattern only produces 97 exact
            // binary fractions that never sit on a rounding boundary.
            let mut lcg = 0x2f6e2b1u32;
            let input: Vec<f32> = (0..n_in)
                .map(|_| {
                    lcg = lcg.wrapping_mul(1_103_515_245).wrapping_add(12_345);
                    let unit = (lcg >> 8) as f32 / 16_777_216.0;
                    unit * 3.0 - 1.5
                })
                .collect();

            // CPU reference: the AVX2 kernel over the whole tensor.
            let q8k = crate::ops::quant::quantize_row_q8_k(&input);
            let row_bytes = n_in / 256 * block_bytes;
            let cpu_fn = cpu_iq_vec_dot(format);
            let mut cpu_output = vec![0.0f32; n_out];
            for (row, out) in cpu_output.iter_mut().enumerate() {
                *out = cpu_fn(&weight[row * row_bytes..(row + 1) * row_bytes], &q8k);
            }

            // GPU: the full tensor in one dispatch.
            let mut gpu_output = vec![0.0f32; n_out];
            match matmul_iq(
                &context,
                format,
                weight,
                &input,
                1,
                n_in,
                n_out,
                &mut gpu_output,
            ) {
                Ok(()) => {}
                Err(VulkanError::UnsupportedShape(e)) => {
                    eprintln!("[skip] {label} UnsupportedShape: {e}");
                    continue;
                }
                Err(error) => panic!("{label} GPU matmul failed: {error}"),
            }

            let mut mismatches = 0usize;
            for (i, (g, c)) in gpu_output.iter().zip(cpu_output.iter()).enumerate() {
                if g.to_bits() != c.to_bits() {
                    mismatches += 1;
                    if mismatches <= 4 {
                        eprintln!(
                            "{label} row {i}: gpu={g} ({:08x}) cpu={c} ({:08x})",
                            g.to_bits(),
                            c.to_bits()
                        );
                    }
                }
            }
            assert_eq!(
                mismatches, 0,
                "{label}: GPU vs CPU {mismatches}/{n_out} rows differ"
            );
            eprintln!("[iq-gpu] {label}: {n_out} rows bit-identical to CPU AVX2");

            // At rows=1 `record_linear_dispatch` swaps Q4_K/Q5_K to the
            // cooperative variant (Q6_K has none), so the row kernel needs a
            // rows=2 pass to stay covered. Both input rows are identical, so
            // each GPU row must match the same CPU reference.
            if matches!(
                format,
                GpuWeightFormat::Q4_K | GpuWeightFormat::Q5_K | GpuWeightFormat::Q6_K
            ) {
                let batched_input: Vec<f32> = input.iter().chain(input.iter()).copied().collect();
                let mut batched_output = vec![0.0f32; 2 * n_out];
                match matmul_iq(
                    &context,
                    format,
                    weight,
                    &batched_input,
                    2,
                    n_in,
                    n_out,
                    &mut batched_output,
                ) {
                    Ok(()) => {}
                    Err(VulkanError::UnsupportedShape(e)) => {
                        eprintln!("[skip] {label} rows=2 UnsupportedShape: {e}");
                        continue;
                    }
                    Err(error) => panic!("{label} rows=2 GPU matmul failed: {error}"),
                }
                let mut row_kernel_mismatches = 0usize;
                for (row_row, g) in batched_output.chunks(n_out).enumerate() {
                    for (i, (gv, cv)) in g.iter().zip(cpu_output.iter()).enumerate() {
                        if gv.to_bits() != cv.to_bits() {
                            row_kernel_mismatches += 1;
                            if row_kernel_mismatches <= 4 {
                                eprintln!(
                                    "{label} rows=2 row {row_row} out {i}: \
                                     gpu={gv} ({:08x}) cpu={cv} ({:08x})",
                                    gv.to_bits(),
                                    cv.to_bits()
                                );
                            }
                        }
                    }
                }
                assert_eq!(
                    row_kernel_mismatches,
                    0,
                    "{label}: rows=2 row kernel vs CPU {row_kernel_mismatches}/{} differ",
                    2 * n_out
                );
                eprintln!("[iq-gpu] {label}: rows=2 row kernel bit-identical to CPU AVX2");
            }
        }
    }

    /// Replay real activation rows dumped from the CPU reference prefill
    /// (`RMI_DUMP_NORMED_LAYER`/`RMI_DUMP_NORMED_DIR`) through the production
    /// Q5_K V projection. Random activations pass bit-exactly while the real
    /// layer-23 stream flips two F16 cache entries, so the real values are
    /// the only way to reproduce a value-dependent divergence.
    #[test]
    fn q5_k_v_projection_replays_dumped_activations_bitwise() {
        use crate::core::tensor::GGMLType;
        let context = match VulkanContext::new() {
            Ok(ctx) => ctx,
            Err(_) => return,
        };
        if context.is_software_icd() {
            eprintln!("[skip] software ICD detected");
            return;
        }
        let (dir, layer) = match (
            std::env::var("RMI_DUMP_NORMED_DIR"),
            std::env::var("RMI_DUMP_NORMED_LAYER"),
        ) {
            (Ok(dir), Ok(layer)) => (std::path::PathBuf::from(dir), layer),
            _ => {
                eprintln!("[skip] RMI_DUMP_NORMED_DIR/LAYER not set");
                return;
            }
        };
        let prefix = format!("normed_L{layer}_");
        let mut chunks: Vec<(usize, usize, Vec<u8>)> = Vec::new();
        let entries = match std::fs::read_dir(&dir) {
            Ok(entries) => entries,
            Err(error) => panic!("dump dir {dir:?} unreadable: {error}"),
        };
        for entry in entries.flatten() {
            let name = entry.file_name().to_string_lossy().into_owned();
            if !name.starts_with(&prefix) || !name.ends_with(".f32") {
                continue;
            }
            let middle = name
                .strip_prefix(&prefix)
                .and_then(|rest| rest.strip_suffix(".f32"))
                .unwrap_or_default();
            let mut base = None;
            let mut rows = None;
            for part in middle.split('_') {
                if let Some(value) = part.strip_prefix("base") {
                    base = value.parse::<usize>().ok();
                }
                if let Some(value) = part.strip_prefix("rows") {
                    rows = value.parse::<usize>().ok();
                }
            }
            if let (Some(base), Some(rows)) = (base, rows) {
                match std::fs::read(entry.path()) {
                    Ok(bytes) => chunks.push((base, rows, bytes)),
                    Err(error) => panic!("dump {name} unreadable: {error}"),
                }
            }
        }
        if chunks.is_empty() {
            panic!("{dir:?} holds no {prefix}*.f32 dumps");
        }
        chunks.sort_by_key(|(base, _, _)| *base);

        let path = "models/Qwen3-0.6B-GGUF/Qwen3-0.6B-UD-Q3_K_XL.gguf";
        let loader = match GGUFLoader::from_file(path) {
            Ok(loader) => loader,
            Err(_) => panic!("{path} not present"),
        };
        let tensor_name = format!("blk.{layer}.attn_v.weight");
        let tensor = loader
            .tensors()
            .iter()
            .find(|t| t.name == tensor_name)
            .unwrap_or_else(|| panic!("{path}: no {tensor_name} tensor"));
        assert_eq!(tensor.ggml_type, GGMLType::Q5K);
        let n_in = tensor.dims[0] as usize;
        let n_out = tensor.dims[1] as usize;
        let weight = loader.tensor_slice(&tensor_name).unwrap();
        let format = GpuWeightFormat::Q5_K;
        let (block_elements, block_bytes, _) = format.layout();
        assert_eq!(weight.len(), n_out * (n_in / block_elements) * block_bytes);
        let cpu_fn = cpu_iq_vec_dot(format);
        let row_bytes = n_in / block_elements * block_bytes;

        for (base, rows, bytes) in chunks {
            assert_eq!(bytes.len(), rows * n_in * 4, "dump base {base}");
            let input: Vec<f32> = bytes
                .chunks_exact(4)
                .map(|word| f32::from_le_bytes([word[0], word[1], word[2], word[3]]))
                .collect();
            let mut cpu_output = vec![0.0f32; rows * n_out];
            for row in 0..rows {
                let q8k =
                    crate::ops::quant::quantize_row_q8_k(&input[row * n_in..(row + 1) * n_in]);
                for (out_row, out) in cpu_output[row * n_out..(row + 1) * n_out]
                    .iter_mut()
                    .enumerate()
                {
                    *out = cpu_fn(&weight[out_row * row_bytes..], &q8k);
                }
            }
            let mut gpu_output = vec![0.0f32; rows * n_out];
            match matmul_iq(
                &context,
                format,
                weight,
                &input,
                rows,
                n_in,
                n_out,
                &mut gpu_output,
            ) {
                Ok(()) => {}
                Err(VulkanError::UnsupportedShape(e)) => {
                    panic!("dump base {base} UnsupportedShape: {e}");
                }
                Err(error) => panic!("dump base {base} GPU matmul failed: {error}"),
            }
            let mut mismatches = 0usize;
            for (i, (g, c)) in gpu_output.iter().zip(cpu_output.iter()).enumerate() {
                if g.to_bits() != c.to_bits() {
                    mismatches += 1;
                    if mismatches <= 8 {
                        eprintln!(
                            "dump base {base} row {} out {}: gpu={g} ({:08x}) cpu={c} ({:08x})",
                            i / n_out,
                            i % n_out,
                            g.to_bits(),
                            c.to_bits()
                        );
                    }
                }
            }
            assert_eq!(
                mismatches,
                0,
                "dump base {base}: GPU vs CPU {mismatches}/{} differ",
                rows * n_out
            );
            eprintln!("[v-proj] base {base} rows {rows}: bit-identical to CPU AVX2");
        }
    }

    /// Q8_0 twin of the q5_k replay above, on the shape where the 4B
    /// contract still fails. Feeds the CPU prefill's dumped `normed`
    /// activations through both production paths -- CPU
    /// (`quantize_q8_0_into` + AVX2 matmul) and GPU (`matmul_iq`, which
    /// quantizes on device before the grouped dp4a matmul) -- and requires
    /// bit-identical outputs. A pass here moves the layer-0 row-2
    /// divergence out of quantize/matmul and into rms_norm or
    /// qk-norm-rope.
    #[test]
    fn q8_0_projection_replays_dumped_activations_bitwise() {
        use crate::core::tensor::GGMLType;
        let (dir, layer) = match (
            std::env::var("RMI_Q8_REPLAY_DIR"),
            std::env::var("RMI_Q8_REPLAY_LAYER"),
        ) {
            (Ok(dir), Ok(layer)) => (std::path::PathBuf::from(dir), layer),
            _ => {
                eprintln!("[skip] RMI_Q8_REPLAY_DIR/LAYER not set");
                return;
            }
        };
        let context = match VulkanContext::new() {
            Ok(ctx) => ctx,
            Err(_) => return,
        };
        if context.is_software_icd() {
            eprintln!("[skip] software ICD detected");
            return;
        }
        let prefix = format!("cpu_L{layer}_");
        let mut chunks: Vec<(usize, usize, Vec<u8>)> = Vec::new();
        let entries = match std::fs::read_dir(&dir) {
            Ok(entries) => entries,
            Err(error) => panic!("dump dir {dir:?} unreadable: {error}"),
        };
        for entry in entries.flatten() {
            let name = entry.file_name().to_string_lossy().into_owned();
            if !name.starts_with(&prefix) || !name.ends_with("_normed.f32") {
                continue;
            }
            let middle = name
                .strip_prefix(&prefix)
                .and_then(|rest| rest.strip_suffix("_normed.f32"))
                .unwrap_or_default();
            let mut base = None;
            let mut rows = None;
            for part in middle.split('_') {
                if let Some(value) = part.strip_prefix("base") {
                    base = value.parse::<usize>().ok();
                }
                if let Some(value) = part.strip_prefix("rows") {
                    rows = value.parse::<usize>().ok();
                }
            }
            if let (Some(base), Some(rows)) = (base, rows) {
                match std::fs::read(entry.path()) {
                    Ok(bytes) => chunks.push((base, rows, bytes)),
                    Err(error) => panic!("dump {name} unreadable: {error}"),
                }
            }
        }
        if chunks.is_empty() {
            panic!("{dir:?} holds no {prefix}*_normed.f32 dumps");
        }
        chunks.sort_by_key(|(base, _, _)| *base);

        let path = "models/Qwen3-4B-GGUF/Qwen3-4B-Q8_0.gguf";
        let loader = match GGUFLoader::from_file(path) {
            Ok(loader) => loader,
            Err(_) => panic!("{path} not present"),
        };
        let tensor_name = format!("blk.{layer}.attn_q.weight");
        let tensor = loader
            .tensors()
            .iter()
            .find(|t| t.name == tensor_name)
            .unwrap_or_else(|| panic!("{path}: no {tensor_name} tensor"));
        assert_eq!(tensor.ggml_type, GGMLType::Q8_0);
        let n_in = tensor.dims[0] as usize;
        let n_out = tensor.dims[1] as usize;
        let weight = loader.tensor_slice(&tensor_name).unwrap();
        let format = GpuWeightFormat::Q8_0;
        let (block_elements, block_bytes, _) = format.layout();
        assert_eq!(weight.len(), n_out * (n_in / block_elements) * block_bytes);
        let blocks = n_in.div_ceil(32);

        for (base, rows, bytes) in chunks {
            assert_eq!(bytes.len(), rows * n_in * 4, "dump base {base}");
            let input: Vec<f32> = bytes
                .chunks_exact(4)
                .map(|word| f32::from_le_bytes([word[0], word[1], word[2], word[3]]))
                .collect();
            let mut cpu_output = vec![0.0f32; rows * n_out];
            let mut q8 = vec![0u8; rows * n_in];
            let mut scales = vec![0.0f32; rows * blocks];
            for row in 0..rows {
                crate::ops::quantize_q8_0_into(
                    &input[row * n_in..(row + 1) * n_in],
                    n_in,
                    &mut q8[row * n_in..(row + 1) * n_in],
                    &mut scales[row * blocks..(row + 1) * blocks],
                );
                crate::ops::kernel::q8_0::dispatch::matmul_q8_0_quantized_range(
                    weight,
                    &q8[row * n_in..(row + 1) * n_in],
                    &scales[row * blocks..(row + 1) * blocks],
                    &mut cpu_output[row * n_out..(row + 1) * n_out],
                    n_in,
                    0,
                    n_out,
                );
            }
            let mut gpu_output = vec![0.0f32; rows * n_out];
            match matmul_iq(
                &context,
                format,
                weight,
                &input,
                rows,
                n_in,
                n_out,
                &mut gpu_output,
            ) {
                Ok(()) => {}
                Err(VulkanError::UnsupportedShape(e)) => {
                    panic!("dump base {base} UnsupportedShape: {e}");
                }
                Err(error) => panic!("dump base {base} GPU matmul failed: {error}"),
            }
            let mut mismatches = 0usize;
            for row in 0..rows {
                for col in 0..n_out {
                    let g = gpu_output[row * n_out + col];
                    let c = cpu_output[row * n_out + col];
                    if g.to_bits() != c.to_bits() {
                        mismatches += 1;
                        if mismatches <= 8 {
                            eprintln!(
                                "dump base {base} row {row} out {col}: gpu={g} ({:08x}) cpu={c} ({:08x})",
                                g.to_bits(),
                                c.to_bits()
                            );
                        }
                    }
                }
            }
            assert_eq!(
                mismatches,
                0,
                "dump base {base}: GPU vs CPU {mismatches}/{} differ",
                rows * n_out
            );
            eprintln!("[q-proj] base {base} rows {rows}: bit-identical to CPU AVX2");
        }
    }
}

#[cfg(test)]
mod sim_probe {
    // Rust simulation of the GLSL iq2_xxs body for one row of real data.
    #[test]
    fn iq2_xxs_sim_vs_cpu() {
        let path = "models/Qwen3-0.6B-GGUF/Qwen3-0.6B-UD-IQ2_XXS.gguf";
        let loader = match crate::core::loader::GGUFLoader::from_file(path) {
            Ok(l) => l,
            Err(_) => return,
        };
        let tensor = loader
            .tensors()
            .iter()
            .find(|t| t.name == "blk.0.attn_q.weight")
            .unwrap();
        let weight = loader.tensor_slice(&tensor.name).unwrap();
        let n_in = tensor.dims[0] as usize;
        let input: Vec<f32> = (0..n_in)
            .map(|i| (((i * 31 + 7) % 97) as f32 - 48.0) / 32.0)
            .collect();
        let q8k = crate::ops::quant::quantize_row_q8_k(&input);
        let cpu = crate::ops::quant::vec_dot_iq2_xxs_q8k(&weight[..n_in / 256 * 66], &q8k);

        // Rust sim of the GLSL body exactly as written
        let ks = crate::ops::quant::iq_tables::KSIGNS_IQ2XS;
        let grid = crate::ops::quant::iq_tables::IQ2XXS_GRID;
        let bb = 66usize;
        let mut acc_lane = [0.0f32; 8];
        for block in 0..4usize {
            let rb = block * bb;
            let q8_scale = q8k[block].d;
            let d =
                crate::ops::f16_to_f32(u16::from_le_bytes(weight[rb..rb + 2].try_into().unwrap()))
                    * q8_scale;
            let mut lane = [0i32; 8];
            for g in 0..8usize {
                let a0 =
                    u32::from_le_bytes(weight[rb + 2 + 8 * g..rb + 6 + 8 * g].try_into().unwrap());
                let a1 =
                    u32::from_le_bytes(weight[rb + 6 + 8 * g..rb + 10 + 8 * g].try_into().unwrap());
                let ls = 2u32 * ((a1 >> 28) & 0xf) + 1;
                for k in 0..8usize {
                    let l = k / 2;
                    let gidx = (a0 >> (8 * l)) & 0xff;
                    let sb = ks[((a1 >> (7 * l)) & 0x7f) as usize];
                    let mut dot = 0i32;
                    for m in 0..4usize {
                        let j = 4 * (k % 2) + m;
                        let b = if j < 4 {
                            (grid[gidx as usize] >> (8 * j)) & 0xff
                        } else {
                            (grid[gidx as usize] >> (8 * (j - 4))) & 0xff
                        };
                        let v = if b >= 128 { b as i32 - 256 } else { b as i32 };
                        let sgn = if (sb >> j) & 1 == 1 { -1i32 } else { 1i32 };
                        dot += v * sgn * q8k[block].qs[32 * g + 4 * k + m] as i32;
                    }
                    lane[k] += dot * ls as i32;
                }
            }
            for k in 0..8 {
                acc_lane[k] = d * lane[k] as f32 + acc_lane[k];
            }
        }
        // hsum tree
        let t0 = acc_lane[4] + acc_lane[0];
        let t1 = acc_lane[5] + acc_lane[1];
        let t2 = acc_lane[6] + acc_lane[2];
        let t3 = acc_lane[7] + acc_lane[3];
        let sim = 0.125f32 * ((t0 + t2) + (t1 + t3));
        println!("SIM cpu={cpu} sim={sim}");
    }
}
